namespace EnterpriseNexus.Infrastructure.Workers;

public sealed class DocumentIngestionWorker(
    ChannelReader<DocumentIngestionJob> channelReader,
    IServiceScopeFactory scopeFactory,
    IEmbeddingGenerator<string, Embedding<float>> embeddingGenerator,
    ILogger<DocumentIngestionWorker> logger) : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        logger.LogInformation("Document Ingestion Background Worker started.");

        await foreach (var job in channelReader.ReadAllAsync(stoppingToken))
        {
            try
            {
                using var scope = scopeFactory.CreateScope();
                var db = scope.ServiceProvider.GetRequiredService<NexusDbContext>();

                logger.LogInformation("Processing document {DocumentId} for tenant {TenantId}", job.DocumentId, job.TenantId);

                // 1. Recursive semantic chunking
                var chunks = TextChunker.ChunkText(job.RawText, maxTokensPerChunk: 400, overlapTokens: 50);

                // 2. Batch embedding generation (max 16 chunks per API batch)
                var chunkTexts = chunks.Select(c => c.Content).ToList();
                var embeddings = await embeddingGenerator.GenerateAsync(chunkTexts, cancellationToken: stoppingToken);

                // 3. Persist chunks with pgvector embeddings
                var entities = chunks.Select((chunk, index) => new DocumentChunk
                {
                    Id = Guid.NewGuid(),
                    TenantId = job.TenantId,
                    DocumentId = job.DocumentId,
                    ChunkIndex = index,
                    Content = chunk.Content,
                    TokenCount = chunk.TokenCount,
                    Embedding = new Pgvector.Vector(embeddings[index].Vector.ToArray()),
                    SecurityGroups = job.SecurityGroups
                }).ToList();

                await db.DocumentChunks.AddRangeAsync(entities, stoppingToken);
                await db.SaveChangesAsync(stoppingToken);

                logger.LogInformation("Successfully indexed {Count} chunks for document {DocumentId}", entities.Count, job.DocumentId);
            }
            catch (Exception ex) when (!stoppingToken.IsCancellationRequested)
            {
                logger.LogError(ex, "Error indexing document {DocumentId}", job.DocumentId);
            }
        }
    }
}

public sealed class PostgresHybridSearchService(
    NexusDbContext db,
    IEmbeddingGenerator<string, Embedding<float>> embeddingGenerator) : IHybridSearchService
{
    public async Task<IReadOnlyList<FusedSearchResult>> RetrieveTopChunksAsync(
        Guid tenantId,
        string query,
        int topK = 5,
        CancellationToken ct = default)
    {
        // 1. Generate query embedding
        var queryEmbedding = await embeddingGenerator.GenerateEmbeddingVectorAsync(query, cancellationToken: ct);
        var pgVector = new Pgvector.Vector(queryEmbedding.ToArray());

        // 2. Parallel Vector Search (HNSW Cosine Distance)
        var vectorTask = db.DocumentChunks
            .AsNoTracking()
            .Where(c => c.TenantId == tenantId)
            .OrderBy(c => c.Embedding.CosineDistance(pgVector))
            .Take(25)
            .Select(c => new SearchResultItem(c.Id, c.Document.Title, c.Content, (float)c.Embedding.CosineDistance(pgVector)))
            .ToListAsync(ct);

        // 3. Parallel Lexical Search (Postgres ts_rank BM25 equivalent)
        var lexicalTask = db.DocumentChunks
            .AsNoTracking()
            .Where(c => c.TenantId == tenantId && EF.Functions.ToTsVector("english", c.Content).Matches(EF.Functions.PlainToTsQuery("english", query)))
            .OrderByDescending(c => EF.Functions.ToTsVector("english", c.Content).Rank(EF.Functions.PlainToTsQuery("english", query)))
            .Take(25)
            .Select(c => new SearchResultItem(c.Id, c.Document.Title, c.Content, 1.0f))
            .ToListAsync(ct);

        await Task.WhenAll(vectorTask, lexicalTask);

        // 4. Reciprocal Rank Fusion
        return ReciprocalRankFusionEngine.Fuse(await vectorTask, await lexicalTask, topK);
    }
}
